  9→#include "utils.cuh"
 10→
 11→#define THREADS 256
 12→#define BLOCKS(TB, N) (TB * N + THREADS - 1) / THREADS
 13→#define FULL_MASK 0xffffffff
 14→
 15→template <typename scalar_t, ReductionType REDUCE, int TB>
 16→__global__ void
 17→segment_csr_kernel(const scalar_t *src_data,
 18→                   const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
 19→                   scalar_t *out_data, int64_t *arg_out_data, size_t N,
 20→                   size_t E) {
 21→
 22→  // Each warp processes exactly `32/TB` rows and aggregates all row values
 23→  // via a parallel reduction.
 24→
 25→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
 26→  int row_idx = thread_idx / TB;
 27→  int lane_idx = thread_idx & (TB - 1);
 28→
 29→  if (row_idx < N) {
 30→    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
 31→    int64_t row_start = __ldg(indptr_info.data + offset);
 32→    int64_t row_end = __ldg(indptr_info.data + offset +
 33→                            indptr_info.strides[indptr_info.dims - 1]);
 34→
 35→    scalar_t val = Reducer<scalar_t, REDUCE>::init();
 36→    int64_t arg, arg_tmp;
 37→
 38→    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E;
 39→    for (int64_t src_idx = row_start + lane_idx; src_idx < row_end;
 40→         src_idx += TB) {
 41→      Reducer<scalar_t, REDUCE>::update(&val, src_data[offset + src_idx], &arg,
 42→                                        src_idx);
 43→    }
 44→
 45→#pragma unroll
 46→    for (int i = TB / 2; i > 0; i /= 2) {
 47→      // Parallel reduction inside a single warp.
 48→      if (REDUCE == MIN || REDUCE == MAX)
 49→        arg_tmp = SHFL_DOWN_SYNC(FULL_MASK, arg, i);
 50→      Reducer<scalar_t, REDUCE>::update(
 51→          &val, SHFL_DOWN_SYNC(FULL_MASK, val, i), &arg, arg_tmp);
 52→    }
 53→
 54→    if (lane_idx == 0) {
 55→      Reducer<scalar_t, REDUCE>::write(out_data + row_idx, val,
 56→                                       arg_out_data + row_idx, arg,
 57→                                       row_end - row_start);
 58→    }
 59→  }
 60→}
 61→
 62→template <typename scalar_t, ReductionType REDUCE>
 63→__global__ void segment_csr_broadcast_kernel(
 64→    const scalar_t *src_data,
 65→    const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
 66→    scalar_t *out_data, int64_t *arg_out_data, size_t N, size_t K, size_t E) {
 67→
 68→  // Each thread processes exactly one row. It turned out that is more
 69→  // efficient than using shared memory due to avoiding synchronization
 70→  // barriers.
 71→
 72→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
 73→  int row_idx = thread_idx / K;
 74→  int lane_idx = thread_idx % K;
 75→
 76→  if (thread_idx < N * K) {
 77→    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
 78→    int64_t row_start = __ldg(indptr_info.data + offset);
 79→    int64_t row_end = __ldg(indptr_info.data + offset +
 80→                            indptr_info.strides[indptr_info.dims - 1]);
 81→
 82→    scalar_t val = Reducer<scalar_t, REDUCE>::init();
 83→    int64_t arg;
 84→
 85→    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E * K;
 86→    for (int64_t src_idx = row_start; src_idx < row_end; src_idx++) {
 87→      Reducer<scalar_t, REDUCE>::update(
 88→          &val, src_data[offset + K * src_idx + lane_idx], &arg, src_idx);
 89→    }
 90→
 91→    Reducer<scalar_t, REDUCE>::write(out_data + thread_idx, val,
 92→                                     arg_out_data + thread_idx, arg,
 93→                                     row_end - row_start);
 94→  }
 95→}
