 97→std::tuple<torch::Tensor, std::optional<torch::Tensor>>
 98→segment_csr_cuda(torch::Tensor src, torch::Tensor indptr,
 99→                 std::optional<torch::Tensor> optional_out,
100→                 std::string reduce) {
101→  CHECK_CUDA(src);
102→  CHECK_CUDA(indptr);
103→  if (optional_out.has_value())
104→    CHECK_CUDA(optional_out.value());
105→  c10::cuda::MaybeSetDevice(src.get_device());
106→
107→  CHECK_INPUT(src.dim() >= indptr.dim());
108→
109→  auto sizes = indptr.sizes().vec();
110→  for (auto i = 0; i < indptr.dim() - 1; i++)
111→    sizes[i] = src.size(i);
112→  indptr = indptr.expand(sizes);
113→
114→  auto dim = indptr.dim() - 1;
115→
116→  src = src.contiguous();
117→
118→  torch::Tensor out;
119→  if (optional_out.has_value()) {
120→    out = optional_out.value().contiguous();
121→    for (int i = 0; i < out.dim(); i++)
122→      if (i != dim)
123→        CHECK_INPUT(src.size(i) == out.size(i));
124→    CHECK_INPUT(src.numel() == 0 || out.size(dim) == indptr.size(dim) - 1);
125→  } else {
126→    sizes = src.sizes().vec();
127→    sizes[dim] = std::max<int64_t>(indptr.size(dim) - 1, 0);
128→    out = torch::empty(sizes, src.options());
129→  }
130→
131→  std::optional<torch::Tensor> arg_out = std::nullopt;
132→  int64_t *arg_out_data = nullptr;
133→  if (reduce2REDUCE.at(reduce) == MIN || reduce2REDUCE.at(reduce) == MAX) {
134→    arg_out = torch::full(out.sizes(), src.size(dim), indptr.options());
135→    arg_out_data = arg_out.value().data_ptr<int64_t>();
136→  }
137→
138→  if (src.numel() == 0) {
139→    if (!optional_out.has_value())
140→      out.fill_(0);
141→    return std::make_tuple(out, arg_out);
142→  }
143→
144→  auto N = out.size(dim) * (indptr.numel() / indptr.size(-1));
145→  auto K = out.numel() / N;
146→  auto E = src.size(dim);
147→
148→  auto indptr_info = at::cuda::detail::getTensorInfo<int64_t, int>(indptr);
149→  auto stream = at::cuda::getCurrentCUDAStream();
150→  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
151→    auto src_data = src.data_ptr<scalar_t>();
152→    auto out_data = out.data_ptr<scalar_t>();
153→
154→    AT_DISPATCH_REDUCTION_TYPES(reduce, [&] {
155→      if (K == 1) {
156→        segment_csr_kernel<scalar_t, REDUCE, 1>
157→            <<<BLOCKS(32, N), THREADS, 0, stream>>>(
158→                src_data, indptr_info, out_data, arg_out_data, N, E);
159→      } else {
160→        segment_csr_broadcast_kernel<scalar_t, REDUCE>
161→            <<<BLOCKS(1, N * K), THREADS, 0, stream>>>(
162→                src_data, indptr_info, out_data, arg_out_data, N, K, E);
163→      }
164→    });
165→  });
166→
167→  return std::make_tuple(out, arg_out);
168→}
