219→torch::Tensor gather_csr_cuda(torch::Tensor src, torch::Tensor indptr,
220→                              std::optional<torch::Tensor> optional_out) {
221→  CHECK_CUDA(src);
222→  CHECK_CUDA(indptr);
223→  if (optional_out.has_value())
224→    CHECK_CUDA(optional_out.value());
225→  c10::cuda::MaybeSetDevice(src.get_device());
226→
227→  CHECK_INPUT(src.dim() >= indptr.dim());
228→
229→  auto sizes = indptr.sizes().vec();
230→  for (auto i = 0; i < indptr.dim() - 1; i++)
231→    sizes[i] = src.size(i);
232→  indptr = indptr.expand(sizes);
233→
234→  auto dim = indptr.dim() - 1;
235→  CHECK_INPUT(src.size(dim) == 0 || src.size(dim) == indptr.size(dim) - 1);
236→
237→  src = src.contiguous();
238→
239→  torch::Tensor out;
240→  if (optional_out.has_value()) {
241→    out = optional_out.value().contiguous();
242→    for (auto i = 0; i < out.dim(); i++)
243→      if (i != dim)
244→        CHECK_INPUT(src.size(i) == out.size(i));
245→  } else {
246→    auto sizes = src.sizes().vec();
247→    if (src.numel() > 0) {
248→      sizes[dim] = indptr.flatten()[-1].cpu().data_ptr<int64_t>()[0];
249→    } else {
250→      sizes[dim] = 0;
251→    }
252→    out = torch::empty(sizes, src.options());
253→  }
254→
255→  if (src.numel() == 0) {
256→    if (!optional_out.has_value())
257→      out.fill_(0);
258→    return out;
259→  }
260→
261→  auto N = src.size(dim) * (indptr.numel() / indptr.size(-1));
262→  auto K = src.numel() / N;
263→  auto E = out.size(dim);
264→
265→  auto indptr_info = at::cuda::detail::getTensorInfo<int64_t, int>(indptr);
266→  auto stream = at::cuda::getCurrentCUDAStream();
267→  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
268→    auto src_data = src.data_ptr<scalar_t>();
269→    auto out_data = out.data_ptr<scalar_t>();
270→
271→    if (K == 1)
272→      gather_csr_kernel<scalar_t, 4><<<BLOCKS(1, 4 * N), THREADS, 0, stream>>>(
273→          src_data, indptr_info, out_data, N, E);
274→    else
275→      gather_csr_broadcast_kernel<scalar_t>
276→          <<<BLOCKS(1, N * K), THREADS, 0, stream>>>(src_data, indptr_info,
277→                                                     out_data, N, K, E);
278→  });
279→
280→  return out;
281→}
